MultiLanguageSpellData['it'][339340] = {name = "[q5]Sagacia di Norgannon", additional_info = "Abilità dell'Incisione Runica\n[q2]Lanciare un incantesimo fornisce Sagacia, che si accumula fino a 10 volte. Quando ci si muove, è possibile lanciare incantesimi in movimento per 0.5 s per ogni accumulo di Sagacia.\n(100ms di recupero)\n[q]Incisione Runica su: Gambe, Piedi, Schiena\n[q]Fonte: Per acquisire questo ricordo, devi avere la reputazione Riverito con la Corte dei Mietitori e aver sbloccato Incisione Runica."}
MultiLanguageSpellData['it'][339341] = {name = "Fine della Notte", additional_info = "[q0][Item Effect]Istantaneo\n[q]Le abilità hanno una bassa probabilità di fornire Calar della Notte, aumentando l'indice di celerità di 456 per 12 s. Quando Calar della Notte termina, l'indice di celerità si riduce di 112 per 8 s."}
