MultiLanguageSpellData['it'][340078] = {name = "[q5]Piccola Lama Tossica", additional_info = "Abilità dell'Incisione Runica\n[q2]Aumenta i danni inflitti da Stilettata del 500% e ne azzera il costo in energia.\n[q]Incisione Runica su: Fianchi, Piedi\n[q]Fonte: Missione: La Gran Banca\n[q]Richiede: Ladro"}
MultiLanguageSpellData['it'][340079] = {name = "[q5]Essenza di Zannacremisi", additional_info = "Abilità dell'Incisione Runica\n[q2]Le abilità che forniscono punti combo hanno una probabilità di infettare il bersaglio con Zannacremisi, infliggendo 0 danni da sanguinamento in 6 s e rigenerando salute pari al 50% dei danni inflitti.\n(Possibilità di Apparire:30%, 200ms di recupero)\n[q]Incisione Runica su: Testa, Spalle, Dito\n[q]Fonte: Bottino Incursione: Generali della Legione di Pietra\n[q]Richiede: Ladro"}
MultiLanguageSpellData['it'][340080] = {name = "[q5]Polvere d'Ombra Rinvigorente", additional_info = "Abilità dell'Incisione Runica\n[q2]Sparizione riduce il tempo di recupero restante delle altre abilità di 20 s.\n[q]Incisione Runica su: Collo, Torso\n[q]Fonte: Acquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\n[q]Richiede: Ladro"}
MultiLanguageSpellData['it'][340081] = {name = "[q5]Farabutto Ardito", additional_info = "Abilità dell'Incisione Runica\n[q2]Affondo Venefico aumenta la probabilità di critico dei tuoi veleni del 15% e i suoi colpi critici generano 1 energia.\n[q]Incisione Runica su: Piedi, Schiena\n[q]Fonte: Bottino Incursione: Il Concilio del Sangue\n[q]Richiede: Ladro (Assassinio)"}
MultiLanguageSpellData['it'][340082] = {name = "[q5]Lama Spietata", additional_info = "Abilità dell'Incisione Runica\n[q2]Mutilazione infligge il 45% di danni da sanguinamento aggiuntivi in 8 s.\n\n Aumenta i danni inflitti da Affondo Venefico del 5% per ogni tuo effetto di sanguinamento sul bersaglio.\n[q]Incisione Runica su: Spalle, Mani, Schiena\n[q]Fonte: Bottino: Torgast, Torre dei Dannati. Mort'regar, Blocco 3+\n[q]Richiede: Ladro (Assassinio)"}
MultiLanguageSpellData['it'][340083] = {name = "[q5]Fregio di Zoldyck", additional_info = "Abilità dell'Incisione Runica\n[q2]Aumenta del 30% i danni da sanguinamento e da veleno inflitti ai bersagli con meno del 30% di salute restante.\n[q]Incisione Runica su: Gambe, Piedi\n[q]Fonte: Bottino: Torgast, Torre dei Dannati. Interstizi dei Cuorfreddo, Blocco 3+\n[q]Richiede: Ladro (Assassinio)"}
MultiLanguageSpellData['it'][340084] = {name = "[q5]Pezza del Calcavespro", additional_info = "Abilità dell'Incisione Runica\n[q2]Il tempo di recupero restante di Stigma Letale si riduce di 1 s ogni 30 energia consumata.\n[q]Incisione Runica su: Torso, Dito\n[q]Fonte: Bottino Spedizione: Evocanebbie\n[q]Richiede: Ladro (Assassinio)"}
MultiLanguageSpellData['it'][340085] = {name = "[q5]Vimini di Pelleverde", additional_info = "Abilità dell'Incisione Runica\n[q2]In Mezzo agli Occhi ha una probabilità del 20% per punto combo di aumentare i danni inflitti dal successivo Colpo di Pistola del 300%.\n[q]Incisione Runica su: Testa, Fianchi\n[q]Fonte: Bottino Incursione: Picchiapoltiglia\n[q]Richiede: Ladro (Fuorilegge)"}
MultiLanguageSpellData['it'][340086] = {name = "[q5]Talismano dell'Astuzia", additional_info = "Abilità dell'Incisione Runica\n[q2]L'allenamento permette di riconoscere e volgere a proprio vantaggio il naturale flusso del combattimento. Assalto Funesto aumenta gradualmente i danni inflitti fino al 15%. L'effetto massimo dura 12 s prima di dissolversi e iniziare poi un nuovo ciclo.\n[q]Incisione Runica su: Collo, Polsi\n[q]Fonte: Bottino Boss Esterno: Mortanis\n[q]Richiede: Ladro (Fuorilegge)"}
MultiLanguageSpellData['it'][340087] = {name = "[q5]Fluidità", additional_info = "Abilità dell'Incisione Runica\n[q2]Scarica d'Adrenalina aumenta i danni inflitti del 8%. Inoltre, fornisce una probabilità che durante Fendenti Furiosi si attivi l'effetto Scarica d'Adrenalina per 3 s.\n[q]Incisione Runica su: Spalle, Dito\n[q]Fonte: Bottino Spedizione: Ventunax\n[q]Richiede: Ladro (Fuorilegge)"}
MultiLanguageSpellData['it'][340088] = {name = "[q5]Schioppo Nascosto", additional_info = "Abilità dell'Incisione Runica\n[q2]Quando Assalto Funesto colpisce una volta aggiuntiva, fornisce una probabilità del 40% che il successivo Colpo di Pistola spari 3 volte aggiuntive.\n[q]Incisione Runica su: Polsi, Mani\n[q]Fonte: Bottino: Torgast, Torre dei Dannati. Forge dell'Anima, Blocco 3+\n[q]Richiede: Ladro (Fuorilegge)"}
MultiLanguageSpellData['it'][340089] = {name = "[q5]Atto Finale", additional_info = "Abilità dell'Incisione Runica\n[q2]Sventramento, Perforazione e Polvere Nera aumentano i danni inflitti dalla successiva mossa risolutiva del 25%.\n[q]Incisione Runica su: Torso, Schiena\n[q]Fonte: Bottino Incursione: Sire Denathrius\n[q]Richiede: Ladro (Scaltrezza)"}
MultiLanguageSpellData['it'][340090] = {name = "[q5]Frammento d'Anima di Akaari", additional_info = "Abilità dell'Incisione Runica\n[q2]Dopo aver lanciato Assalto d'Ombra o Colpo Basso, il bersaglio subisce un Assalto d'Ombra dalle ombre dopo 2 s, con un'efficacia del 25%.\n[q]Incisione Runica su: Testa, Collo, Mani\n[q]Fonte: Bottino: Torgast, Torre dei Dannati. Sala di Skoldus, Blocco 3+\n[q]Richiede: Ladro (Scaltrezza)"}
