MultiLanguageSpellData['it'][347411] = {name = "Fango Appiccicoso", additional_info = "[q0][Item Effect]Portata di 40 m\nIstantaneo\n[q]Lancia del fango su una posizione. La velocità di tutti i nemici entro 8 m si riduce del 50% finché restano nell'area d'effetto. La trappola persiste per 30 s. Utilizzabile solo quando ci si trova all'esterno nelle Terretetre."}
MultiLanguageSpellData['it'][347412] = {name = "Lancio Trappola dell'Inseguitore d'Anime", additional_info = "Lancio Trappola dell'Inseguitore d'Anime Livello 80\nPortata di 15 m\n{1 s di lancio} {1 min di recupero}\n[q]Piazza la trappola entro 15 m. La trappola riduce la velocità di movimento dei nemici che la calpestano del 30 % e infligge ( 131642 * 20 / 4) danni da ombra in 20 s. Utilizzabile solo quando ci si trova all'esterno nelle Terretetre."}
MultiLanguageSpellData['it'][347413] = {name = "Ricerca dei Ricordi Perduti", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Perlustra le cronache alla ricerca di ricordi perduti, ricevendo un ricordo di un potere leggendario per la tua classe che non possiedi già."}
