MultiLanguageSpellData['it'][353872] = {name = "Alagreve di Oblio del Peccato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Con l'Animum tornato a fluire a Oblio del Peccato, la Madrepietra ha potuto infonderlo in questi Litogeni, rendendoli degli alleati preziosi per le battaglie future.\"\nCongrega:\nVenthyr\nZona:\nRevendreth"}
MultiLanguageSpellData['it'][353873] = {name = "Alagreve Pallido", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Gli alagreve non conoscono la paura e sono praticamente indistruttibili. Perfetti per un assalto alla Fauce.\"\nCongrega:\nVenthyr\nMercante:\nDuchessa Mynx\nZona:\nKorthia\nCosto:\n1.000\nImpresa:\nAll'attacco"}
MultiLanguageSpellData['it'][353875] = {name = "Aquilon Elisio", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Con l'Animum tornato a fluire nella Forgia Eterna del Bastione, è possibile tornare a lavorare ai piani per l'aquilon dei Centurioni.\"\nCongrega:\nKyrian\nZona:\nBastione"}
MultiLanguageSpellData['it'][353877] = {name = "Aquilon Indegno", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Costruiti originariamente dagli Indegni sfruttando dei progetti rubati, questi potenti Centurioni si stanno affermando in tutte le Terretetre.\"\nCongrega:\nKyrian\nBottino:\nSpaccamondi Selvaggio\nZona:\nKorthia"}
MultiLanguageSpellData['it'][353878] = {name = "Lancio", additional_info = "[q0][Item Effect]Portata di 40 m\n{2 s di lancio} {6 s di recupero}\n[q]Scaglia una lancia contro un Araldo Giurafauce, trascinandolo verso di te."}
MultiLanguageSpellData['it'][353880] = {name = "Aquilon dell'Ascendente", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Gli aquilon possono trasportare rapidamente Aspiranti, Factotum e persino Ascesi. Certe volte volare con le proprie ali è stancante.\"\nCongrega:\nKyrian\nMercante:\nAiutante Galos\nZona:\nBastione\nCosto:\n7.500"}
MultiLanguageSpellData['it'][353881] = {name = "Lancio", additional_info = "Portata di 100 m\n{Istantaneo} {6 s di recupero}\n[q]Scaglia una lancia contro un Araldo Giurafauce, trascinandolo verso di te."}
MultiLanguageSpellData['it'][353882] = {name = "[q5]Trasferimento Dilagante", additional_info = "Abilità dell'Incisione Runica\nIstantaneo\n[q2]Aumenta la forza ottenuta da Dovere della Morte del 3% e ne aumenta la durata di 2 s. Quando ci si trova all'interno del proprio Dovere della Morte, la generazione di potenza runica aumenta del 20%.\n[q]Incisione Runica su: Torso, Fianchi\n[q]Fonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\n[q]Richiede: Cavaliere della Morte"}
MultiLanguageSpellData['it'][353883] = {name = "Insetto Necrofago di Maldraxxus", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Gli insetti necrofagi un tempo si trovavano in tutta Maldraxxus, ma molti sono morti a causa dell'assenza di Animum. Ora che l'Animum è tornato a fluire, sono tornati anche loro.\"\nCongrega:\nNecrosignori\nZona:\nMaldraxxus"}
MultiLanguageSpellData['it'][353884] = {name = "Insetto Necrofago Regale", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Solo le forze di Maldraxxus definirebbero un insetto necrofago \"regale\".\"\nCongrega:\nNecrosignori\nMercante:\nSu Zettai\nZona:\nMaldraxxus\nCosto:\n7.500"}
MultiLanguageSpellData['it'][353885] = {name = "Brulicatore del Campo di Battaglia", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Gli insetti necrofagi sono fortemente attratti dall'odore dei cadaveri e si gettano sui campi di battaglia non appena percepiscono la prima vittima.\"\nCongrega:\nNecrosignori\nMercante:\nDuchessa Mynx\nZona:\nKorthia\nCosto:\n1.000\nImpresa:\nAll'attacco"}
