MultiLanguageSpellData['it'][354332] = {name = "Benedizione dell'Anima Maligna", additional_info = "Portata di 50 m\nIstantaneo\nCirca 3 apparenze ogni minuto\n[q]Uno spirito malvagio ti assiste, fornendo ai tuoi attacchi una probabilità di disorientare un nemico per 4 s."}
MultiLanguageSpellData['it'][354333] = {name = "[q5]Delizia Peccaminosa", additional_info = "Abilità dell'Incisione Runica\nIstantaneo\n[q2]Consumare [ Arcano : Lancio Istintivo ][ Fuoco : una carica di Detonazione di Fuoco /\n\nGelo\nMente Fredda ] riduce il tempo di recupero di Specchi del Tormento di 4 s. Se l'effetto di Specchi del Tormento viene dissolto, il tempo di recupero si riduce di 45 s.\n[q]Incisione Runica su: Gambe, Piedi\n[q]Fonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\n[q]Richiede: Mago"}
MultiLanguageSpellData['it'][354334] = {name = "Agganciato!", additional_info = "Portata di 300 m\nIstantaneo\n[q]Coduncino aggancia un personaggio con la coda per 3 s, facendolo sanguinare e infliggendo 736893 danni fisici ogni 1 s per 10 s."}
