MultiLanguageSpellData['it'][354351] = {name = "Destriero Tenebroso del Sanctum", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Solo i luogotenenti più potenti del Carceriere ricevono in dono questi destrieri per perlustrare le sale della torre.\"\nBottino:\nLe Nove\nZona:\nSanctum del Dominio"}
MultiLanguageSpellData['it'][354352] = {name = "Destriero Tenebroso Vincolato all'Anima", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Ve'nari conosce molti modi per infiltrarsi nella Fauce e ostacolare i piani del Carceriere, come vincolare i suoi stessi servitori.\"\nBottino:\nDono Misterioso di Ve'nari\nZona:\nFauce"}
MultiLanguageSpellData['it'][354353] = {name = "Destriero Caduto", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Le urla del destriero riecheggiano in tutta la Fauce mentre continua a cavalcare senza sosta in ogni dove, alla perenne ricerca di una via di fuga dagli eterni tormenti che è stato costretto a subire.\"\nBottino:\nZona:\nFauce"}
MultiLanguageSpellData['it'][354354] = {name = "Mano di Nilganihmaht", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Di tutti i giganti che osarono sfidare il Carceriere, Nilganihmaht fu il più arrogante. A causa della sua ribellione, la mano mozzata del gigante venne nascosta sotto un velo di tormenti e gli anelli che potevano richiamarla vennero sparsi per tutta la Fauce.\"\nZona:\nFauce"}
MultiLanguageSpellData['it'][354355] = {name = "Mano di Salaranga", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Salaranga era la più astuta dei suoi simili e si nascose negli Antri delle Bestie. Colpì l'Esiliato con un'orda di bestie, sue alleate, ma non fece alcuna differenza.\"\nImpresa:\nSpezzare le catene\nZona:\nKorthia e Fauce"}
MultiLanguageSpellData['it'][354356] = {name = "Pellescheggia d'Ambra", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"I colori accesi della fauna di Korthia indicano che hanno pochi predatori naturali oppure che sono abbastanza resistenti da sapersi difendere.\"\nMercante:\nDuchessa Mynx\nZona:\nKorthia\nFazione:\nMarcia della Morte - Riverito\nCosto:\n5.000"}
MultiLanguageSpellData['it'][354357] = {name = "Pellescheggia Cremisi", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Quando Korthia venne trascinata nella Fauce, solo poche specie coriacee sopravvissero.\"\nBottino:\nMalpantano\nZona:\nKorthia"}
MultiLanguageSpellData['it'][354358] = {name = "Zampaoscura", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Zampaoscura, un pellescheggia anziano, era relativamente amichevole e mansueto con gli abitanti di Korthia. Si credeva fosse andato perduto a causa della calamità.\"\nZona:\nKorthia"}
MultiLanguageSpellData['it'][354359] = {name = "Alafina Audace", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Gli alafina di solito stanno alla larga dalle altre specie di Korthia, ma col un po' di tempo e tanta pazienza, anch'essi possono essere addomesticati.\"\nBottino:\nForniture della Marcia della Morte\nZona:\nKorthia"}
MultiLanguageSpellData['it'][354360] = {name = "Alafina Granato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Una tempo, Korthia era famosa per i suoi fiori dal colore rosso acceso. Diverse specie erano solito consumarli o rotolarcisi sopra, assumendo così una colorazione rossa brillante.\"\nBottino:\nReliwik l'Insolente\nZona:\nKorthia"}
MultiLanguageSpellData['it'][354361] = {name = "Alafina di Albascura", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Gli alafina sono presenti in tutta Korthia e nidificano sulle colline più elevate e sugli alberi.\"\nZona:\nKorthia"}
MultiLanguageSpellData['it'][354362] = {name = "Unicorno Girovago", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Un animale curioso e inquisitorio che non vuole far preoccupare il suo padrone, ma si distrae facilmente, specialmente con tutte le nuove cose da vedere a Korthia.\"\nZona:\nKorthia"}
MultiLanguageSpellData['it'][354363] = {name = "Portento Tetro", additional_info = "Istantaneo\n[q]Lo Scriba del Destino Roh-Kalo vincola diversi personaggi alle rune del Telaio dei Destini.\n\n Dopo 9 s, se un personaggio vincolato sta toccando la propria runa assegnata, lo Scriba del Destino infligge 19968 danni da ombra a tutti i personaggi all'interno della runa.\n\n Se una runa termina senza il proprio personaggio vincolato all'interno, lo Scriba del Destino infligge 107829 danni da ombra a tutti i personaggi."}
