MultiLanguageSpellData['it'][354374] = {name = "Flagello della Banshee", additional_info = "Portata illimitata\nIstantaneo\n[q]Sylvanas appesantisce i bersagli con un'afflizione famelica, infliggendo 1 danni da ombra ogni secondo. Si accumula. Se viene dissolta, si condensa in una pozza d'ombra sul terreno. I personaggi che toccano la pozza vengono affetti da Flagello della Banshee , consumando la pozza."}
MultiLanguageSpellData['it'][354376] = {name = "Calci Furenti", additional_info = "{Istantaneo} {20 s di recupero}\n[q]Scompare dai nemici, creando una nuvola di polvere sulla posizione attuale che nasconde le unità alleate per 5 s.\n\n Tubbins può servire il tè mentre si nasconde nella nuvola di polvere."}
