MultiLanguageSpellData['it'][359229] = {name = "Vombatide Cuordiluce", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Gli Illuminati venerano tutte le creazioni dei Primi; tuttavia, per molti di loro, i vombatidi di Zereth Mortis hanno un posto speciale nel cuore. Queste creature sono sia fidate bestie da soma che adorate compagne di viaggio.\"\nMercante:\nVilo\nZona:\nZereth Mortis\nFazione:\nIlluminati - Osannato\nCosto:\n5.000"}
MultiLanguageSpellData['it'][359230] = {name = "Annusacristalli Curioso", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Alla maggior parte dei vombatidi piace scavare nel terreno, ma i fiutatori sembrano avere una dote naturale nel trovare i cristalli nascosti sottoterra e si radunano intorno ai depositi più grandi.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageSpellData['it'][359231] = {name = "Vombatide Oscuro", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Lo schema per sintetizzare questi vombatidi oscuri sembra essere apparso in reazione all'invasione dei Giurafauce. Il vombatide risultante sembra diverso, è scuro come gli invasori, ma si comporta normalmente.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageSpellData['it'][359232] = {name = "Vombatide Adornato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"I vombatidi rossi sono considerati fortunati dagli Illuminati. Al loro arrivo a Zereth Mortis, la prima creatura che incontrarono fu proprio un vombatide rosso.\"\nProfessione:\nSintesi di Protoforma"}
