MultiLanguageSpellData['it'][359317] = {name = "Wen Lo, la Riva del Fiume", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"I fiumi di Pandaria, proprio come Wen Lo, sono imprevedibili di natura. Possono rimanere calmi, portando acqua nei campi, o provocare inondazioni, portando la rovina. Wen Lo ci ricorda che bisogna sapersi adattare alle sfide della vita.\"\nNegozio di gioco"}
MultiLanguageSpellData['it'][359318] = {name = "Tomo Magico Volteggiante", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Nelle profondità dimenticate della biblioteca di Dalaran, questo tomo in formato gigante è stato trovato a svolazzare all'impazzata in una stanza. Apri le pagine di questo libro infuso di magia arcana e fatti dare un passaggio verso una magica avventura.\"\nImpresa:\nUn tour delle torri\nCategoria:\nViaggi nel Tempo"}
