MultiLanguageSpellData['it'][359364] = {name = "Vespide Alabronzea", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"I Vespidi Alabronzea sono il risultato del tentativo di sintetizzare una regina vespide senza il resto dell'alveare. Anche se nessun mortale ha mai scoperto come sintetizzare un alveare, le alibronzee restano delle cavalcature affidabili così come sono.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageSpellData['it'][359366] = {name = "Ronzio", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Bzz bzz bzz, bzz bzz! Bzz bzz bzz bzz bzz. bzz bzz bzz, bzz bzz bzz.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageSpellData['it'][359367] = {name = "Volarabbia Forgiato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Non c'è nulla che possa farti sentire vivo come cavalcare in giro per il regno della Morte in sella a un essere che ti odia.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageSpellData['it'][359372] = {name = "Falconide Adattato alla Fauce", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Sin dall'incursione del Carceriere, Zereth Mortis ha sintetizzato dei nuovi falconidi fatti per resistere all'influenza corrompente della Fauce.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageSpellData['it'][359373] = {name = "Falconide Predatore", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Il Falconide Predatore è uno dei più aggressivi esemplari della propria specie, particolarmente adatto alla sua nicchia ecologica. Non avendo bisogno di alcuna ulteriore modifica, quelli sintetizzati oggi sono identici a quelli creati in passato.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageSpellData['it'][359374] = {name = "Protezione dalla Negazione", additional_info = "Portata di 30 m\n1.5 s di lancio\n[q]Protegge il bersaglio, infliggendo danni cosmici agli attaccanti per 10 s.\n(250ms di recupero)"}
MultiLanguageSpellData['it'][359375] = {name = "Protezione dalla Negazione", additional_info = "Portata di 50 m\nIstantaneo\n[q]Infligge danni cosmici."}
MultiLanguageSpellData['it'][359376] = {name = "Elicide Bronzeo", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Alcuni elicidi di Zereth Mortis hanno uno strano guscio metallico. Questi sono generalmente color bronzo, proprio come il metallo estratto anche dal più novizio dei minatori, con l'eccezione che la costruzione di questa creatura va ben oltre le abilità di un novizio.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageSpellData['it'][359377] = {name = "Prototipo di Turbolumaca Fallito", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Questa creatura non è stata progettata dai Primi, ma da un essere sconosciuto che ha tentato di creare una creatura molto veloce. Inutile dire che il tentativo è fallito, perché questa cavalcatura è molto lenta.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageSpellData['it'][359378] = {name = "Elicide Scarlatto", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Questa particolare colorazione rossastra è chiaramente intenzionale, ma l'unica altra differenza tra questi e altri elicidi è una caratteristica mancanza di melma.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageSpellData['it'][359379] = {name = "Aurelide Scintillante", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Anche se è stato creato per difendere il Sepolcro dei Primi, ora che la sua funzione primaria si è esaurita, segue ciecamente i tuoi comandi.\"\nImpresa:\nGloria dell'incursore del Sepolcro\nCategoria:\nSpedizioni e incursioni"}
MultiLanguageSpellData['it'][359380] = {name = "Inseguitore delle Profondità", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Catturate a Zereth Mortis, alcune di queste meduse andarono perdute quando la nave dei bracconieri affondò. Trovarono una nuova casa nelle profondità del Grande Mare.\"\nEmporio"}
MultiLanguageSpellData['it'][359381] = {name = "Aurelide Criptico", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"I Codici dei Primi sono al di là di ogni comprensione mortale. Un effetto curioso della lingua è che, per ragioni ignote, alcuni aurelidi sono attratti dai mortali che aspirano a rivelarne i misteri.\"\nImpresa:\nDalla A alla Zereth\nCategoria:\nTerretetre"}
MultiLanguageSpellData['it'][359383] = {name = "Sterminio Immediato", additional_info = nil}
MultiLanguageSpellData['it'][359384] = {name = "Chiamata all'Azione di Bron", additional_info = "Istantaneo\n[q]Dopo aver lanciato 75 incantesimi e abilità d'attacco o di cura, il successivo incantesimo o abilità evoca Bron, che respinge istantaneamente i nemici e attacca e cura i tuoi bersagli per 30 s."}
