MultiLanguageSpellData['it'][359399] = {name = "Pioggia di Stelle", additional_info = "Portata di 200 m\nIstantaneo\n[q]Richiama delle ondate di stelle cadenti sui nemici entro 40 m, infliggendo [9 * (24.9% of Spell power)] danni astrali in 8 s Lanci multipli potrebbero sovrapporsi.[ Combustione Eterea : Aumenta la durata degli effetti attivi di Fuoco Lunare e Fuoco Solare di 3 s ]"}
MultiLanguageSpellData['it'][359400] = {name = "Palle Chiodate", additional_info = "Istantaneo\n[q]Il Fabbro del Dolore rilascia delle palle chiodate che rotolano attraverso il pavimento della stanza, infliggendo 400 danni fisici ai personaggi sulla traiettoria e stordendoli per 8 s."}
MultiLanguageSpellData['it'][359401] = {name = "Strisciatore della Genesi", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Gli Illuminati che hanno studiato i taracnidi credono che questa varietà sia una delle prime creature ad aver mai messo piede su Zereth Mortis.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageSpellData['it'][359402] = {name = "Camminatore Taracnide", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Questi taracnidi creano le loro tane negli angoli più oscuri di Zereth Mortis, uscendo fuori solo per cacciare (e, a volte, per trasportare qualcuno in giro).\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageSpellData['it'][359403] = {name = "Saltatore Ineffabile", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Questi taracnidi si muovono con uno scopo sconosciuto agli altri, e rispondono solo a un ordine dall'alto. Di qualsiasi cosa si tratti, sembra che l'assistenza ai mortali che hanno bisogno di un passaggio sia contemplata negli ordini. Per ora.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageSpellData['it'][359407] = {name = "Calcamorte Distorto", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Pura energia turbinante contenuta in una forma coesa, si piega solo alla volontà di coloro abbastanza forti da vincolarlo.\"\nImpresa:\nMaestro delle Chiavi di Shadowlands: Stagione 3\nCategoria:\nSpedizioni"}
