MultiLanguageSpellData['it'][360006] = {name = "Nube Necrofaga", additional_info = "2.5 s di lancio\n[q]Mal'Ganis crea una nube di insetti intorno al bersaglio, infliggendo 7310 danni da piaga ogni 1 s. L'effetto cresce d'intensità nel tempo.\n\n Se il bersaglio si avvicina a meno di 5 m da un altro personaggio, gli insetti saltano su quel personaggio, azzerando l'intensità dell'effetto.\n\n Se dissolto, il personaggio resta affetto da Ferite Pungenti ."}
MultiLanguageSpellData['it'][360007] = {name = "[q3]Nucleo di Automa Magicamente Regolato", additional_info = "1.5 s di lancio\nStrumenti:\nVerga Runica d'Incantamento\nReagenti:\nCristallo Eterno (5), Minerale di Progenio , Scheggia Immortale (5)\nMercante:\nOlea Manu\nZona:\nZereth Mortis\nCosto:\n25\n\n[q3]Nucleo di Automa Magicamente Regolato\nReagente d'Artigianato Facoltativo\n\n[q2]Fornisce la seguente proprietà: Le abilità hanno una probabilità di creare un Nucleo di Automa vicino al bersaglio, infliggendo danni e cure.\n[q]Utilizzabile con: Ricette di Shadowlands per armature e accessori rari (blu)."}
MultiLanguageSpellData['it'][360008] = {name = "Nube Necrofaga", additional_info = "Portata di 150 m\nIstantaneo\n[q]Mal'Ganis crea una nube di insetti intorno al bersaglio, infliggendo 7310 danni da piaga ogni 0.5 s. L'effetto cresce d'intensità nel tempo.\n\n Se il bersaglio si avvicina a meno di 5 m da un altro personaggio, gli insetti saltano su quel personaggio, disorientandolo per 1 s e azzerando l'intensità dell'effetto.\n\n Se dissolto, il personaggio resta affetto da Ferite Pungenti ."}
