MultiLanguageSpellData['it'][364854] = {name = "Delizia Peccaminosa", additional_info = "[q]Consumare [ Arcano : Lancio Istintivo ][ Fuoco : una carica di Detonazione di Fuoco /\n\nGelo\nMente Fredda ] riduce il tempo di recupero di Specchi del Tormento di 4 s. Se l'effetto di Specchi del Tormento viene dissolto, il tempo di recupero si riduce di 45 s."}
MultiLanguageSpellData['it'][364855] = {name = "Profondità della Morte", additional_info = "[q]Palla di Fuoco, Dardo di Gelo e Detonazione Arcana hanno una probabilità di attivare Stirpe della Morte per 8 s. Mentre si è in forma di Mago Scheletrico, i danni magici inflitti aumentano del 1% per ogni nemico colpito da Palla di Fuoco, Dardo di Gelo e Detonazione Arcana."}
MultiLanguageSpellData['it'][364856] = {name = "Cuore dei Silfi", additional_info = "[q]Potere Mutevole può essere canalizzato in movimento. Ogni nemico colpito da Potere Mutevole aumenta la probabilità di critico e la celerità del 1%, fino a un massimo del 10% per 15 s."}
