MultiLanguageSpellData['it'][367907] = {name = "Infusione Celestiale", additional_info = "[q0][Item Effect]Istantaneo\n[q]Quando si raggiunge un'Eclissi Lunare, si crea una Furia di Elune al 20% di efficacia che segue il bersaglio attuale per 8 s."}
MultiLanguageSpellData['it'][367909] = {name = "Volo Sospeso", additional_info = "{Istantaneo} {35 s di recupero}\n[q]Permette di scattare, aumentando la velocità di movimento del 30% per (6 + 0 ) s.\n\n Permette di lanciare incantesimi da Evocatore in movimento. Non ha effetto sugli incantesimi Potenziati."}
MultiLanguageSpellData['it'][367910] = {name = "[q3]Rabbia Risonante", additional_info = "[q0][Anima Power]Istantaneo\n[q]Quando possiede un Vombatide Senza Nucleo, Pocopoc fornisce una probabilità di lanciare un effetto Brama di Sangue per 8 s a ogni uccisione."}
MultiLanguageSpellData['it'][367911] = {name = "[q3]Tessuto Risonante", additional_info = "[q0][Anima Power]Istantaneo\n[q]Quando possiede un Taracnide Senza Nucleo, Pocopoc fornisce una probabilità di stordire e avvelenare gli attaccanti in mischia."}
MultiLanguageSpellData['it'][367912] = {name = "[q3]Carapace Risonante", additional_info = "[q0][Anima Power]Istantaneo\n[q]Quando possiede uno Scarabeide Senza Nucleo, Pocopoc riduce i tuoi danni subiti del 10%."}
MultiLanguageSpellData['it'][367913] = {name = "[q3]Muco Risonante", additional_info = "[q0][Anima Power]Istantaneo\n[q]Quando possiede un Elicide Senza Nucleo, Pocopoc fornisce una probabilità all'attacco di ridurre le velocità d'attacco e di lancio d'incantesimi del nemico."}
MultiLanguageSpellData['it'][367914] = {name = "[q3]Ricrescita Risonante", additional_info = "[q0][Anima Power]Istantaneo\n[q]Quando possiede un Geomentale Senza Nucleo, Pocopoc aumenta periodicamente lo scudo rigenerativo intorno a te. Lo scudo si infrange quando si subiscono danni pari al 5% della salute massima. Si accumula fino a 3 volte."}
MultiLanguageSpellData['it'][367918] = {name = "Santificazione Cinerea", additional_info = "[q0][Covenant Ability]{20% della base mana} {Portata di 30 m}\n{1.5 s di lancio} {4 min di recupero}\n[q]Santifica l'area bersaglio per 30 s. I nemici nell'area d'effetto subiscono fino a [(55% of Spell power) * 30 / 5.19999981] danni da ombra e gli alleati vengono curati di massimo [(36% of Spell power) * 30 / 5.19999981] salute, quantità ridotte se ci sono più di 0 bersagli.\n\n All'interno dell'area d'effetto, è possibile lanciare Martello dell'Ira su qualsiasi bersaglio, infliggendo il 100% di danni aggiuntivi."}
