MultiLanguageSpellData['it'][367931] = {name = "Catene del Dominio", additional_info = "Catene del Dominio Livello 80\n[q0][Item Effect]Portata di 15 m\n{Istantaneo} {3 min di recupero}\n[q]Spinge un aculeo nel bersaglio, infliggendo 5489 danni fisici e creando un collegamento a catena per 20 s. Finché la catena persiste, il 25 % di tutti i danni inflitti al bersaglio vengono immagazzinati all'interno della catena, fino a un massimo di 2329 danni.\n\n Allontanarsi dal bersaglio strappa la catena, infliggendo danni da ombra pari ai danni immagazzinati a tutti i nemici entro 8 m."}
MultiLanguageSpellData['it'][367932] = {name = "Fato Tetro", additional_info = "Portata di 300 m\nIstantaneo\n[q]Quando vengono sconfitti, i Riflessi Tetri potenziano i Riflessi restanti, aumentandone la celerità del 150%."}
MultiLanguageSpellData['it'][367937] = {name = "Rabbia Risonante", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Quando possiede un Vombatide Senza Nucleo, Pocopoc fornisce una probabilità di lanciare un effetto Brama di Sangue per 8 s a ogni uccisione.\nL'effetto dura 15 min. Funziona solo nelle zone esterne delle Terretetre o a Oribos."}
MultiLanguageSpellData['it'][367938] = {name = "Tessuto Risonante", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Quando possiede un Taracnide Senza Nucleo, Pocopoc fornisce una probabilità di stordire e avvelenare gli attaccanti in mischia.\nL'effetto dura 15 min. Funziona solo nelle zone esterne delle Terretetre o a Oribos."}
MultiLanguageSpellData['it'][367939] = {name = "Carapace Risonante", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Quando possiede uno Scarabeide Senza Nucleo, Pocopoc riduce i tuoi danni subiti del 10%. \nL'effetto dura 15 min. Funziona solo nelle zone esterne delle Terretetre o a Oribos."}
MultiLanguageSpellData['it'][367940] = {name = "Muco Risonante", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Quando possiede un Elicide Senza Nucleo, Pocopoc fornisce una probabilità all'attacco di ridurre le velocità d'attacco e di lancio d'incantesimi del nemico. \nL'effetto dura 15 min. Funziona solo nelle zone esterne delle Terretetre o a Oribos."}
MultiLanguageSpellData['it'][367941] = {name = "Ricrescita Risonante", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Quando possiede un Geomentale Senza Nucleo, Pocopoc aumenta periodicamente lo scudo rigenerativo intorno a te. Lo scudo si infrange quando si subiscono danni pari al 5% della salute massima. Si accumula fino a 3 volte. \nL'effetto dura 15 min. Funziona solo nelle zone esterne delle Terretetre o a Oribos."}
