MultiLanguageSpellData['it'][367950] = {name = "Speranza del Leone", additional_info = "Speranza del Leone Livello 80\n[q0][Item Effect]Circa 20 apparenze ogni minuto\n[q]Gli incantesimi hanno una probabilità di fornire Speranza, aumentando l'Intelletto di 17 per 12 s. La probabilità di ottenere Speranza aumenta al diminuire della salute dei bersagli."}
MultiLanguageSpellData['it'][367951] = {name = "Disperazione del Residuo", additional_info = "Disperazione del Residuo Livello 80\n[q0][Item Effect]Circa 20 apparenze ogni minuto\n[q]Gli incantesimi d'attacco hanno una probabilità di affliggere i nemici con Disperazione, aumentando l'effetto delle tue malattie su di loro di 46 per 12 s. La probabilità di affliggere i nemici con Disperazione aumenta all'aumentare della salute dei nemici."}
MultiLanguageSpellData['it'][367952] = {name = "Singolarità Suprema", additional_info = "Singolarità Suprema Livello 80\n[q0][Item Effect][q]Gli incantesimi d'attacco generano accumuli di Singolarità, fornendo 5 indice di versatilità e velocità per accumulo, fino a un massimo di 20 .\n\n Quando raggiungono 20 accumuli, questi bonus raddoppiano e persistono per 20 s. Al termine, si perdono tutti gli accumuli e bisogna attendere 40 s prima di avvicinarsi di nuovo alla Singolarità.\n(100ms di recupero)"}
MultiLanguageSpellData['it'][367953] = {name = "Giudizio Distorto", additional_info = "[q0][Item Effect]Portata di 30 m\n{Istantaneo} {4 min di recupero}\n[q]Rimuove l'anima del bersaglio affinché riceva il giudizio finale.\n\n Uccidere quest'anima la invia all'aldilà che merita, fornendoti un Dono Distorto per 60 s in base alla sua destinazione."}
