MultiLanguageSpellData['it'][377451] = {name = "Globo di Gelo Evocato", additional_info = "[q0][Item Effect]Portata di 40 m\nIstantaneo\n[q]Se hai più del 65 % del mana massimo, lancia il Globo di Gelo al bersaglio, infliggendo 3041 danni da gelo.\n\n Se hai meno del 65 % del mana massimo, bevi dal Globo di Gelo per rigenerare 562 mana istantaneamente."}
MultiLanguageSpellData['it'][377452] = {name = "Icona dell'Incarnazione Sussurrante", additional_info = "Icona dell'Incarnazione Sussurrante Livello 80\n[q0][Item Effect][q]Soccombere ai sussurri dell'icona rende Infusi di Gelo , aumentando l'indice di critico di 57 .\n\n Combattere insieme ad altri alleati Infusi di Terra o Fuoco ha una probabilità di fornirti 16 della loro statistica di infusione per 12 s.\n\n Infusione in base alla specializzazione attuale.\n(1.5s di recupero)"}
MultiLanguageSpellData['it'][377453] = {name = "Dono della Mangiatempeste", additional_info = "Dono della Mangiatempeste Livello 80\n[q0][Item Effect]{Istantaneo} {3 min di recupero}\n[q]Accettare la tempesta trasforma in un Elementale dell'Aria Primordiale, immobilizzando sul posto per 10 s.\n\n In questa forma, i venti tutt'intorno infliggono 311 danni da natura ogni secondo a tutti i nemici entro 10 m, danni che si intensificano del 10 % ogni secondo finché la trasformazione non si placa."}
MultiLanguageSpellData['it'][377454] = {name = "Rubino Tremante", additional_info = "Rubino Tremante Livello 80\n[q0][Item Effect]Circa 5 apparenze ogni minuto\n[q]Gli attacchi generano Forza Concussiva, fornendo 3 potenza d'attacco per accumulo.\n\n Al raggiungimento di 10 accumuli, le successive 3 abilità in mischia emettono un'onda d'urto frontale, infliggendo 903 danni da natura aggiuntivi a tutti i nemici lungo una linea. Le onde d'urto infliggono danni aggiuntivi ai nemici con salute alta.\n(500ms di recupero)"}
MultiLanguageSpellData['it'][377455] = {name = "Trappola Mortale di Brinarossa", additional_info = "Trappola Mortale di Brinarossa Livello 80\n[q0][Item Effect]Portata di 45 m\n{Istantaneo} {2 min di recupero}\n[q]Infligge 2197 danni da gelo al bersaglio, intrappolando lui e tutti i nemici in una Ragnatela Cristallina per 15 s.I nemici all'interno hanno una velocità di movimento ridotta del 15% e subiscono 174 danni da gelo quando un nemico all'interno viene colpito.\n\n Danni aumentati per ogni nemico intrappolato, fino a un massimo di 5. Danni per bersaglio ridotti oltre i 5 nemici."}
MultiLanguageSpellData['it'][377456] = {name = "Via delle Correnti controllate", additional_info = "Via delle Correnti controllate Livello 80\n[q0][Item Effect][q]I colpi critici hanno una probabilità di creare Elettricità Statica, aumentando la velocità d'attacco del 2 % per accumulo. L'effetto può verificarsi solo una volta ogni 1 s. Al raggiungimento di 10 accumuli, l'elettricità si impenna, aumentando la velocità di movimento del 30 % per 12 s. Durante il picco, gli attacchi automatici folgorano il bersaglio e 1 nemico vicino, infliggendo 319 danni da natura.\n\n Al termine dell'effetto, si viene ancorati al terreno per 1 min e non è possibile generare Elettricità Statica.\n(1.5s di recupero)"}
MultiLanguageSpellData['it'][377457] = {name = "Totem Totale del Maestro", additional_info = "[q0][Item Effect][q]Assume una Postura Elementale. Schivare o parare un attacco scatena un potente Contrattacco Elementale contro i nemici frontali, permettendo poi di assumere la postura successiva.\n\n Può attivarsi solo una volta ogni 30 s.\n(30s di recupero)"}
MultiLanguageSpellData['it'][377458] = {name = "Postura Elementale: Terra", additional_info = "[q0][Item Effect]Portata di 100 m\nIstantaneo\n[q]Assume una Postura Elementale. Schivare o parare un attacco scatena un potente Contrattacco Elementale contro i nemici frontali, permettendo poi di assumere la postura successiva.\n\n Può attivarsi solo una volta ogni 30 s."}
MultiLanguageSpellData['it'][377459] = {name = "Postura Elementale: Fuoco", additional_info = "Portata di 100 m\nIstantaneo\n[q]Assume una Postura Elementale. Schivare o parare un attacco scatena un potente Contrattacco Elementale contro i nemici frontali, permettendo poi di assumere la postura successiva.\n\n Può attivarsi solo una volta ogni 30 s."}
MultiLanguageSpellData['it'][377461] = {name = "Postura Elementale: Aria", additional_info = "[q0][Item Effect]Portata di 100 m\nIstantaneo\n[q]Assume una Postura Elementale. Schivare o parare un attacco scatena un potente Contrattacco Elementale contro i nemici frontali, permettendo poi di assumere la postura successiva.\n\n Può attivarsi solo una volta ogni 30 s."}
MultiLanguageSpellData['it'][377462] = {name = "Promessa della Custode della Progenie", additional_info = "Promessa della Custode della Progenie Livello 80\n[q0][Item Effect]Portata di 100 m\n{1 s di lancio} {5 s di recupero}\n[q]Indica un altro personaggio a cui legarti, diventandone il Guardiano per 1 ora.\n\n Finché siete legati, il vostro indice di versatilità aumenta di [ 11 * (1 - 20 / 100)] e rigenerate [ 45 * (1 - 40 / 100)] salute ogni secondo. Se vi trovate a meno di 15 m di distanza, i bonus aumentano.\n\nValido solo per le specializzazioni da guaritore."}
MultiLanguageSpellData['it'][377463] = {name = "Fiocaluce Frenetica", additional_info = "Fiocaluce Frenetica Livello 80\n[q0][Item Effect]Portata di 40 m\n{Canalizzato (2 s di lancio} {) 2 min di recupero}\n[q]Canalizza per 2 s, scatenando una furiosa raffica di fiamme attorno al bersaglio, infliggendo [ 951 * (8) * (1 + Versatility)] danni da fuoco al bersaglio con la probabilità di infliggere danni aggiuntivi ai nemici vicini.\n\n Se un personaggio alleato muore, il tempo di recupero si riduce di 90 s."}
MultiLanguageSpellData['it'][377464] = {name = "Invocazione Disperata", additional_info = "Invocazione Disperata Livello 80\n[q0][Item Effect]Portata di 45 m\n{Istantaneo} {4 min di recupero}\n[q]Scatena una pericolosa corrente di fulmini, infliggendo 5877 danni da natura al bersaglio e 31 danni da natura a se stessi. I danni inflitti a se stessi aumentano in base agli accumuli di Odio."}
MultiLanguageSpellData['it'][377465] = {name = "Invocazione Disperata", additional_info = "Invocazione Disperata Livello 80\n[q0][Item Effect][q]Lanciare incantesimi fornisce accumuli di Odio, riducendo permanentemente il tempo di recupero di questo monile di 1 s fino al termine del combattimento. L'effetto si accumula fino a 180 volte.\n(1s di recupero)"}
MultiLanguageSpellData['it'][377466] = {name = "Tempesta Adirata", additional_info = "Tempesta Adirata Livello 80\n[q0][Item Effect][q]Gli incantesimi e le abilità permettono di accumulare Perfidia. Al raggiungimento di 5 accumuli, un Dardo della Tempesta Adirato si sposta sul bersaglio attuale, infliggendo [ 86 * (6) * (1 + Versatility)] danni da natura in 3 s.\n\n Al termine, il dardo torna indietro, aumentando gli accumuli di Perfidia necessari per il lancio di 1 e aumentando in modo permanente i danni inflitti da Dardo della Tempesta Adirato, finché uno muore.\n(1s di recupero)"}
MultiLanguageSpellData['it'][377467] = {name = "Carica Fulminante", additional_info = "Portata illimitata\nIstantaneo\n[q]Raszageth carica i bersagli con l'elettricità, 3 s. Al termine, la carica esplode, infliggendo 88328 danni da natura a tutti i personaggi nell'area d'impatto e saltando sul personaggio più vicino colpito dall'esplosione.\n\n Ogni volta che Carica Fulminante salta su un nuovo personaggio, la sua portata si riduce e il personaggio precedente viene affetto da Carica Persistente ."}
