MultiLanguageSpellData['it'][382321] = {name = "[q4]Vecchio Fumetto", additional_info = "5 s di lancio 3\nStrumenti:\nChiave ad Arco , Microavvitatore Giromatico\nReagenti:\nLega d'Ossidiana Ardente (4), Polvere Esplosiva a Combustione Continua (8), Condensatore di Arciluce (2), Telaio Meccanico Rinforzato , Scintilla (#247) (2)\nReagenti Facoltativi:\nInfondi di potere (#111) , Personalizza statistiche secondarie (#125) , Consapevolezza Illustre (#93) , Aggiungi abbellimento (#226) , Pezzi di Ricambio (#230)\nBottino:\nAssalto degli Zaqali\nZona:\nAberrus, il Crogiolo d'Ombra\nRicetta:\nAcquistabile alla Casa d'Aste\n\n[q4]Vecchio Fumetto\nSi vincola alla raccolta\nA distanza Arma da fuoco\n406 - 754 Danni Velocità 3.00\n(193.3 danni per secondo)\n+257 Agilità\n+416 Tempra\n[q2]+ 239 Attributo casuale 1\n[q2]+ 239 Attributo casuale 2\nIntegrità 120 / 120\n58"}
MultiLanguageSpellData['it'][382327] = {name = "Catasta di Fuochi d'Artificio", additional_info = "1.5 s di lancio\nStrumenti:\nChiave ad Arco , Microavvitatore Giromatico\nReagenti:\nFuoco Stimolante (3), Pelle Petrosa , Polvere Esplosiva a Combustione Continua (2)\nPesca:\nRicetta in Bottiglia Draconica\nRicetta:\nAcquistabile alla Casa d'Aste\n\nSi vincola alla raccolta\n[q]\"Contiene un assortimento di fuochi d'artificio di diverse ere e culture.\"\n[q2]<Destra Aprire>"}
MultiLanguageSpellData['it'][382329] = {name = "[q3]Canna da Pesca di Khaz'gorite", additional_info = "3.5 s di lancio\nStrumenti:\nChiave ad Arco , Microavvitatore Giromatico\nReagenti:\nMinerale di Khaz'gorite (10), Ingranaggi Oliati (4), Condensatore di Arciluce (2), Telaio Meccanico Rinforzato\nReagenti Facoltativi:\nConsapevolezza Illustre (#93) , Pezzi di Ricambio (#230)\nBottino:\nSacca Incontaminata di Tesori di Drospo\nMercante:\nGrande Drospus\nCosto:\nMoneta d'Oro delle Isole\nRicetta:\nAcquistabile alla Casa d'Aste\n\n[q3]Canna da Pesca di Khaz'gorite\nSi vincola alla raccolta\nAttrezzo di Pesca\n[q2]+ 90 Percezione\n[q2]Equipaggia: Aumenta la Competenza in Pesca delle Isole dei Draghi di 15.\nRichiedePesca\n(1)"}
MultiLanguageSpellData['it'][382332] = {name = "[q3]Anatrobot", additional_info = "10 s di lancio\nStrumenti:\nChiave ad Arco , Microavvitatore Giromatico\nReagenti:\nPiuma di Uccello Contornata (60), Modulatore di Anatrobot , Malygosite (2), Manciata di Viti di Serevite (4), Bobina a Molla Folgorante , Ingranaggi Oliati (2), Telaio Meccanico Rinforzato\nMercante:\nCapo Magor\nZona:\nSponde del Risveglio\nFazione:\nSpedizione delle Scaglie di Drago - Fama 21\nCosto:\n200\n\nMercante:\nCatalogatrice Jakes\nZona:\nSponde del Risveglio\nFazione:\nSpedizione delle Scaglie di Drago - Fama 21\nCosto:\n200\n\n[q3]Anatrobot\nSi vincola alla raccolta\n[q2]Usa: Ti insegna a evocare e congedare questa mascotte.\n[q2]Clicca col pulsante destro per evocare e congedare questa mascotte.\nRichiede dal livello 1 al 80 ( 80)"}
MultiLanguageSpellData['it'][382335] = {name = "Fuoco d'Artificio dello Stormo Verde", additional_info = "1.5 s di lancio\nStrumenti:\nChiave ad Arco , Microavvitatore Giromatico\nReagenti:\nScaglie Adamantine , Polvere Esplosiva a Combustione Continua (2)\nMercante:\nRabul\nZona:\nValdrakken\nFazione:\nConsorzio degli Artigiani - Stimato\nCosto:\n200\n\n[q2]Usa: Spara a un set di fuochi d'artificio in onore dello Stormo dei Draghi Verdi."}
MultiLanguageSpellData['it'][382336] = {name = "[q3]A.I.U.T.O.", additional_info = "2 s di lancio\nStrumenti:\nChiave ad Arco , Microavvitatore Giromatico\nReagenti:\nIra Risvegliata (3), Contrassegno d'Onore (15), Manciata di Viti di Serevite (6), Polvere Esplosiva a Combustione Continua (4), Telaio Meccanico Rinforzato\nMercante:\nEraneth\nZona:\nValdrakken\nCosto:\n3\n\n[q3]A.I.U.T.O.\nSi vincola alla raccolta\nGiocattolo\n[q2]Usa: Spara un bengala di segnalazione per avvertire gli alleati vicini di un pericolo imminente.\n\n Utilizzabile solo nei campi di battaglia. I bengala di segnalazione non possono essere sparati in un'area dalla stessa fazione più di una volta ogni 3 min. (2 Min Recupero)\n[q]\"Appello Importante e Urgente da Tracciare Ora!\""}
