MultiLanguageSpellData['it'][384686] = {name = "Eruzione Energetica", additional_info = "1.5 s di lancio\n[q]La Tempesta Furente sperimenta un'Eruzione Energetica, aumentando la velocità d'attacco in mischia del 100% per 8 s e facendo sì che gli attacchi in mischia infliggano 736893 danni da natura aggiuntivi."}
