MultiLanguageSpellData['it'][384688] = {name = "Deposito di Draconium", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]I Depositi di Draconium sono rari da trovare sulle Isole dei Draghi, ma sono più spesso visibili nei luoghi più difficili da raggiungere."}
MultiLanguageSpellData['it'][384689] = {name = "Divide et Impera", additional_info = "[q0]Specializzazione de Tank – Riga 1 talento di PvP\n[q][ Soffio degli Eoni / Alito del Drago] crea una cortina di fuoco che nasconde il campo visivo ai nemici al di fuori e brucia coloro che lo attraversano, infliggendo (480% of Spell power) danni da fuoco. Dura 6 s."}
MultiLanguageSpellData['it'][384690] = {name = "Deposito Fuso di Draconium", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]I Depositi di Draconium sono rari da trovare sulle Isole dei Draghi, ma sono più spesso visibili nei luoghi più difficili da raggiungere.\n\n Talvolta sono avvolti dalle fiamme, in particolare nelle regioni geologicamente attive. Il calore insopportabile spesso è un deterrente per i minatori novizi, che si tengono lontani dai suoi numerosi Fuochi Stimolanti.\n\n I minatori specializzati in nodi Fusi ottengono il seguente effetto con l'Estrazione:\n\n Furia Lavica :\nTi avvolge in fiamme, così da infliggere 1721 danni da fuoco agli attaccanti. Dura 2 min."}
MultiLanguageSpellData['it'][384691] = {name = "Divide et Impera", additional_info = "Portata di 100 m\nIstantaneo\n[q]Alito del Drago crea un muro di fuoco per 8 s, nascondendo il campo visivo al di là del muro. I nemici che attraversano il muro subiscono 1 danni."}
MultiLanguageSpellData['it'][384692] = {name = "Deposito di Serevite", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]La serevite è il minerale più comune di tutte le Isole dei Draghi. Anche se si trova più spesso nelle regioni di montagna, può essere rinvenuta anche vicino ai corsi d'acqua.\nProfessione:\nEstrazione (1)"}
MultiLanguageSpellData['it'][384693] = {name = "Deposito Ricco di Draconium", additional_info = "Portata di 5 m\n5.3 s di lancio\n[q]I Depositi di Draconium sono rari da trovare sulle Isole dei Draghi, ma sono più spesso visibili nei luoghi più difficili da raggiungere.\n\n I depositi ricchi sono particolarmente densi di minerali, con grande gioia dei minatori che li trovano."}
