MultiLanguageSpellData['it'][385633] = {name = "Aura del Risoluto", additional_info = "[q]Insegna Aura della Concentrazione, Aura della Devozione e Aura del Crociato:\n\nAura della Concentrazione :\nRiduce la durata degli effetti di interruzione e silenziamento sui membri del gruppo o dell'incursione entro 40 m del 30%.\n\n Aura della Devozione :\nLa devozione incoraggia i membri del gruppo o dell'incursione entro 40 m, riducendone i danni subiti del 3%.\n\n Aura del Crociato :\nAumenta la velocità su cavalcatura del 20% per tutti i membri del gruppo o dell'incursione entro 40 m."}
MultiLanguageSpellData['it'][385634] = {name = "Incoscienza", additional_info = "Portata di 100 m\nIstantaneo\n[q]Maruuk agita la sua arma e scatena una violenta folata di vento, infliggendo 15 danni da natura ai personaggi bersaglio e respingendoli indietro.\n\n Inoltre, affligge i personaggi colpiti con Incoscienza per 6 s."}
