MultiLanguageSpellData['it'][389406] = {name = "Deposito Toccato dai Titani di Draconium", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]I Depositi di Draconium sono rari da trovare sulle Isole dei Draghi, ma sono più spesso visibili nei luoghi più difficili da raggiungere.\n\n A volte vengono potenziati dai piccoli costrutti di ricerca dei Titani. Fortunatamente, questi nodi preferiscono benedire i minatori che li lavorano, invece che rispondere ai colpi.\n\n Fornisce il seguente effetto con l'Estrazione:\n\n Potenziale Illuminato :\nAumenta la velocità di movimento del 15%. Le statistiche secondarie dei raccoglitori specializzati nelle erbe Toccate dai Titani aumentano del 3%."}
MultiLanguageSpellData['it'][389407] = {name = "Piumadura Furioso", additional_info = "Istantaneo\n[q]Gli incantesimi d'attacco hanno una probabilità di lanciare una Freccia del Cercatore d'Anime contro il bersaglio, infliggendo 0 danni da ombra in 1 min al primo nemico colpito. Se il bersaglio muore mentre ne è affetto, i successivi incantesimi d'attacco lanciano una freccia."}
MultiLanguageSpellData['it'][389408] = {name = "Rabbia di Im'bunata", additional_info = "Portata illimitata\n{Istantaneo} {10 s di recupero}\n[q]Richiama la rabbia di Im'bunata!"}
MultiLanguageSpellData['it'][389409] = {name = "Deposito Primordiale di Draconium", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]I Depositi di Draconium sono rari da trovare sulle Isole dei Draghi, ma sono più spesso visibili nei luoghi più difficili da raggiungere.\n\n Talvolta vengono marchiati dagli elementi primordiali e possono rivelare elementi Stimolanti aggiuntivi quando vengono estratti.\n\n I minatori specializzati in nodi Primordiali ottengono il seguente effetto con l'Estrazione:\n\n Elementi Esplosivi :\nAumenta la riduzione del tempo di recupero di Sovraccarico del 30 %. I minatori specializzati hanno una probabilità di infliggere danni elementali aggiuntivi con gli incantesimi e le abilità. Dura 2 min."}
