MultiLanguageSpellData['it'][389458] = {name = "Vena di Draconium", additional_info = "Portata di 5 m\n5.3 s di lancio\n[q]I Depositi di Draconium sono rari da trovare sulle Isole dei Draghi, ma sono più spesso visibili nei luoghi più difficili da raggiungere. Le vene sono dei depositi significativamente rari che si trovano solo sottoterra, ma sono fonti incredibilmente ricche di materiali per chiunque le trovi."}
MultiLanguageSpellData['it'][389459] = {name = "Deposito Fuso di Serevite", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]La serevite è il minerale più comune di tutte le Isole dei Draghi. Anche se si trova più spesso nelle regioni di montagna, può essere rinvenuta anche vicino ai corsi d'acqua.\n\n Talvolta sono avvolti dalle fiamme, in particolare nelle regioni geologicamente attive. Il calore insopportabile spesso è un deterrente per i minatori novizi, che si tengono lontani dai suoi numerosi Fuochi Stimolanti.\n\n I minatori specializzati in nodi Fusi ottengono il seguente effetto con l'Estrazione:\n\n Furia Lavica :\nTi avvolge in fiamme, così da infliggere 1721 danni da fuoco agli attaccanti. Dura 2 min."}
MultiLanguageSpellData['it'][389460] = {name = "Deposito di Serevite Ricco", additional_info = "Portata di 5 m\n5.3 s di lancio\n[q]La serevite è il minerale più comune di tutte le Isole dei Draghi. Anche se si trova più spesso nelle regioni di montagna, può essere rinvenuta anche vicino ai corsi d'acqua.\n\n I depositi ricchi sono particolarmente densi di minerali, con grande gioia dei minatori che li trovano."}
MultiLanguageSpellData['it'][389461] = {name = "Deposito Toccato dai Titani di Serevite", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]La serevite è il minerale più comune di tutte le Isole dei Draghi. Anche se si trova più spesso nelle regioni di montagna, può essere rinvenuta anche vicino ai corsi d'acqua.\n\n Talvolta vengono potenziati dai piccoli costrutti di ricerca dei Titani. Fortunatamente, questi nodi preferiscono benedire i minatori che li lavorano, invece che rispondere ai colpi.\n\n Fornisce il seguente effetto con l'Estrazione:\n\n Potenziale Illuminato :\nAumenta la velocità di movimento del 15%. Le statistiche secondarie dei raccoglitori specializzati nelle erbe Toccate dai Titani aumentano del 3%."}
MultiLanguageSpellData['it'][389462] = {name = "Deposito Primordiale di Serevite", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]La serevite è il minerale più comune di tutte le Isole dei Draghi. Anche se si trova più spesso nelle regioni di montagna, può essere rinvenuta anche vicino ai corsi d'acqua.\n\n Talvolta vengono marchiati dagli elementi primordiali e possono rivelare elementi Stimolanti aggiuntivi quando vengono estratti.\n\n I minatori specializzati in nodi Primordiali ottengono il seguente effetto con l'Estrazione:\n\n Elementi Esplosivi :\nAumenta la riduzione del tempo di recupero di Sovraccarico del 30 %. I minatori specializzati hanno una probabilità di infliggere danni elementali aggiuntivi con gli incantesimi e le abilità. Dura 2 min."}
