MultiLanguageSpellData['it'][391429] = {name = "Carne alla Fiamma", additional_info = "[q]Vista Spettrale ha un tempo di recupero di 30 s e rivela un demone condannato per 25 s. [ Vendetta : Vildevastazione /\n\nRovina\nRaggio Oculare ] e Lancio Lama infliggono danni letali al demone, aumentando i danni inflitti del 20% per 15 s.\n\n Alla morte, il demone esplode, infliggendo (192.5% of Attack power) danni da ombra ai nemici vicini e rigenerando il 20% della salute massima. L'esplosione infligge danni ridotti oltre 5 bersagli."}
MultiLanguageSpellData['it'][391430] = {name = "Carne alla Fiamma", additional_info = "{Istantaneo} {2 min di recupero}\n[q]Le abilità d'attacco hanno una probabilità di richiamare un demone dal Teatro del Dolore per 25 s. Lancio Lama infligge danni letali al demone, facendolo esplodere alla morte, infliggendo (192.5% of Attack power) danni da ombra ai nemici vicini e rigenerando il 20% della salute massima. L'esplosione infligge danni ridotti oltre i 5 bersagli."}
MultiLanguageSpellData['it'][391431] = {name = "Altofiore Scompigliato", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]L'Altofiore è l'erba più comune di tutte le Isole dei Draghi. La si può trovare praticamente ovunque e su qualsiasi terreno.\n\n Le erbe che crescono sulle alture o nelle regioni ventose, come le Pianure di Ohn'ahra, possono assorbire il potere elementale dell'aria. Quando vengono raccolte, si scatenano potenti folate di vento che respingono indietro l'erbalista. Tuttavia, è un modo efficace per trovare l'Aria Stimolante.\n\n Gli erbalisti specializzati nelle erbe Scompigliate ottengono il seguente effetto alla raccolta:\n\n Scompigliato :\nQuando si cade da più di 40 m, una potente raffica di vento rallenta la caduta."}
MultiLanguageSpellData['it'][391441] = {name = "Sassifraga", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]La Sassifraga è un'erba robusta che può crescere in diversi luoghi. Nonostante sia generalmente diffusa nei luoghi più impervi, come montagne o scogliere, si trova anche nelle pianure o nelle regioni vulcaniche."}
MultiLanguageSpellData['it'][391444] = {name = "Papavero Bolla", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Il Papavero Bolla è un'erba delicata che cresce nelle zone acquatiche delle Isole dei Draghi, quindi lungo i fiumi, sulle coste e nelle caverne umide.\n\n Nonostante il suo aspetto unico il Papavero Bolla non è particolarmente utile. La cosa veramente preziosa è il fungo acquoso che si forma alla sua base."}
