MultiLanguageSpellData['it'][391446] = {name = "Congelamento Solido", additional_info = "Portata illimitata\nIstantaneo\n[q]Il freddo gelido inabilita il personaggio e infligge 52997 danni da gelo ogni 1 s per 10 s. L'effetto non può essere mitigato o evitato."}
MultiLanguageSpellData['it'][391447] = {name = "Scorzatorta", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]La scorzatorta è un'erba verdeggiante che si trova sulle Isole dei Draghi. Si trova dove c'è abbondanza di alberi o foglie."}
