MultiLanguageSpellData['it'][391498] = {name = "Altofiore Impetuoso", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]L'Altofiore è l'erba più comune di tutte le Isole dei Draghi. La si può trovare praticamente ovunque e su qualsiasi terreno.\n\n Si trova sempre in luoghi di conflitti, nei quali si dice che queste erbe abbiano ottenuto proprietà magiche dall'ira di coloro che combattevano nelle vicinanze.\n\n Fornisce il seguente effetto alla raccolta:\n\n Furia della Battaglia :\nFornisce una probabilità di ottenere Ira Stimolante dai personaggi nemici uccisi. Dura 2 min.\n\n Ulteriori estrazioni di minerali o raccolte di erbe aumentano la durata dell'effetto."}
MultiLanguageSpellData['it'][391499] = {name = "Sassifraga Impetuosa", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]La Sassifraga è un'erba robusta che può crescere in diversi luoghi. Nonostante sia generalmente diffusa nei luoghi più impervi, come montagne o scogliere, si trova anche nelle pianure o nelle regioni vulcaniche.\n\n Si trova sempre in luoghi di conflitti, nei quali si dice che queste erbe abbiano ottenuto proprietà magiche dall'ira di coloro che combattevano nelle vicinanze.\n\n Fornisce il seguente effetto alla raccolta:\n\n Furia della Battaglia :\nFornisce una probabilità di ottenere Ira Stimolante dai personaggi nemici uccisi. Dura 2 min.\n\n Ulteriori estrazioni di minerali o raccolte di erbe aumentano la durata dell'effetto."}
MultiLanguageSpellData['it'][391500] = {name = "Sassifraga Decaduta", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]La Sassifraga è un'erba robusta che può crescere in diversi luoghi. Nonostante sia generalmente diffusa nei luoghi più impervi, come montagne o scogliere, si trova anche nelle pianure o nelle regioni vulcaniche.\n\n Le erbe esposte all'essenza del decadimento diventano versioni avvizzite di se stesse. Le piante sono ancora utilizzabili, ma tutti gli aspiranti raccoglitori vengono esposti al decadimento, che li affligge come una malattia. Ne vale comunque la pena, perché queste erbe sono una fonte affidabile di Decadimento Stimolante.\n\n Gli erbalisti specializzati in erbe decadute ottengono il seguente effetto alla raccolta:\n\n Decadimento Controllato :\nLa magia del decadimento ti potenzia, aumentando la velocità di ricarica di Sovraccarico Erba Elementale del 400 %."}
MultiLanguageSpellData['it'][391501] = {name = "Sassifraga Gelata", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]La Sassifraga è un'erba robusta che può crescere in diversi luoghi. Nonostante sia generalmente diffusa nei luoghi più impervi, come montagne o scogliere, si trova anche nelle pianure o nelle regioni vulcaniche.\n\n Quando quest'erba incontra i climi più freddi, o si trova vicino a sorgenti d'acqua, può essere infusa dal gelo elementale. Raccogliere questo tipo di erbe ricopre il terreno di ghiaccio, ma l'erbalista sarà ricompensato per i suoi sforzi con del Gelo Stimolante.\n\n Gli erbalisti specializzati nelle erbe Gelate ottengono il seguente effetto alla raccolta:\n\n Petali Gelidi :\nTi avvolge in una nuvola di gelo che congela temporaneamente qualsiasi nemico si avvicini troppo."}
MultiLanguageSpellData['it'][391502] = {name = "Sassifraga Lussureggiante", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]La Sassifraga è un'erba robusta che può crescere in diversi luoghi. Nonostante sia generalmente diffusa nei luoghi più impervi, come montagne o scogliere, si trova anche nelle pianure o nelle regioni vulcaniche.\n\n Alcune erbe crescono rigogliose e prosperano per le più disparate ragioni, a prescindere dal clima o dalla posizione. Gli erbalisti che trovano questi nodi rari possono recuperare reagenti aggiuntivi."}
MultiLanguageSpellData['it'][391503] = {name = "Sassifraga Toccata dai Titani", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]La Sassifraga è un'erba robusta che può crescere in diversi luoghi. Nonostante sia generalmente diffusa nei luoghi più impervi, come montagne o scogliere, si trova anche nelle pianure o nelle regioni vulcaniche.\n\n Le erbe che crescono nelle zone ricche dell'influenza dei Titani, come le Sponde del Risveglio o Thaldraszus, possono esserne potenziate. Questi tipi di erbe forniscono un dono all'erbalista che si avvicina a loro, e anche dell'Ordine Stimolante.\n\n Gli erbalisti specializzati in erbe toccate dai titani ottengono il seguente effetto alla raccolta:\n\n Potenziale Illuminato :\nAumenta la velocità di movimento del 15%. Le statistiche secondarie dei raccoglitori specializzati nelle erbe Toccate dai Titani aumentano del 3%."}
MultiLanguageSpellData['it'][391504] = {name = "Sassifraga Scompigliata", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]La Sassifraga è un'erba robusta che può crescere in diversi luoghi. Nonostante sia generalmente diffusa nei luoghi più impervi, come montagne o scogliere, si trova anche nelle pianure o nelle regioni vulcaniche.\n\n Le erbe che crescono sulle alture o nelle regioni ventose, come le Pianure di Ohn'ahra, possono assorbire il potere elementale dell'aria. Quando vengono raccolte, si scatenano potenti folate di vento che respingono indietro l'erbalista. Tuttavia, è un modo efficace per trovare l'Aria Stimolante.\n\n Gli erbalisti specializzati nelle erbe Scompigliate ottengono il seguente effetto alla raccolta:\n\n Scompigliato :\nQuando si cade da più di 40 m, una potente raffica di vento rallenta la caduta."}
MultiLanguageSpellData['it'][391505] = {name = "Papavero Bolla Impetuoso", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Il Papavero Bolla è un'erba delicata che cresce nelle zone acquatiche delle Isole dei Draghi, quindi lungo i fiumi, sulle coste e nelle caverne umide.\n\n Nonostante il suo aspetto unico il Papavero Bolla non è particolarmente utile. La cosa veramente preziosa è il fungo acquoso che si forma alla sua base.\n\n Si trova sempre in luoghi di conflitti, nei quali si dice che queste erbe abbiano ottenuto proprietà magiche dall'ira di coloro che combattevano nelle vicinanze.\n\n Fornisce il seguente effetto alla raccolta:\n\n Furia della Battaglia :\nFornisce una probabilità di ottenere Ira Stimolante dai personaggi nemici uccisi. Dura 2 min.\n\n Ulteriori estrazioni di minerali o raccolte di erbe aumentano la durata dell'effetto."}
