MultiLanguageSpellData['it'][393044] = {name = "Eruzione Temporale", additional_info = "Portata di 30 m\nIstantaneo\n[q]L'energia temporale erutta dall'incantatore, espellendo dardi di energia che infliggono 10 danni da arcano a tutti i personaggi entro 30 m dal punto d'impatto e lasciano dietro di sé una pila di sabbia."}
MultiLanguageSpellData['it'][393045] = {name = "Eruzione Temporale", additional_info = "Portata di 30 m\n1.5 s di lancio\n[q]L'energia temporale erutta dall'incantatore, espellendo dardi di energia che infliggono 10 danni da arcano a tutti i personaggi entro 30 m dal punto d'impatto e lasciano dietro di sé una pila di sabbia."}
