MultiLanguageSpellData['it'][393053] = {name = "Punto di Pressione", additional_info = "Istantaneo\n[q]I colpi critici di Calcio del Sole Nascente riducono il tempo di recupero di Pugni della Furia di 5.0 s.\n\n Al termine di Pugni della Furia, la probabilità di critico di Calcio del Sole Nascente aumenta del 40% per 5 s."}
MultiLanguageSpellData['it'][393054] = {name = "Spazzata della Morte", additional_info = "Portata di 100 m\nIstantaneo\n[q]Assale 5 nemici vicini, infliggendo [3 * (27.5614% of Attack power)% + (82.8% of Attack power)%] danni fisici. Infligge danni ridotti oltre 5 bersagli."}
MultiLanguageSpellData['it'][393055] = {name = "Spazzata della Morte", additional_info = "Portata di 100 m\nIstantaneo\n[q]Assale 5 nemici vicini, infliggendo [3 * (27.5614% of Attack power)% + (82.8% of Attack power)%] danni fisici. Infligge danni ridotti oltre 5 bersagli."}
MultiLanguageSpellData['it'][393056] = {name = "Esplosione di Chi", additional_info = "Istantaneo\n[q]Quando si infliggono danni a un bersaglio con Pugni della Furia, si ottiene 1 accumulo di Energia Chi, fino a un massimo di 30 accumuli.\n\n Usare Calcio Rotante della Gru causa un'Esplosione di Chi, che infligge (180% of Attack power) danni da natura a tutti i nemici entro 8 m. Danni ridotti oltre 5 bersagli. I danni aumentano del 5% per ogni accumulo di Energia Chi."}
MultiLanguageSpellData['it'][393057] = {name = "Energia Chi", additional_info = "Istantaneo\n[q]Quando si infliggono danni a un bersaglio con Pugni della Furia, si ottiene 1 accumulo di Energia Chi, fino a un massimo di 30 accumuli.\n\n Usare Calcio Rotante della Gru causa un'Esplosione di Chi, infliggendo (65% of Attack power) danni a tutti i nemici entro 8 m. I danni aumentano del 5% per ogni accumulo di Energia Chi."}
MultiLanguageSpellData['it'][393058] = {name = "Vincolo di Xuen", additional_info = "Istantaneo\n[q]Aumenta i danni di Invocazione: Xuen, la Tigre Bianca del 30% e ne riduce il tempo di recupero di 30 s."}
MultiLanguageSpellData['it'][393059] = {name = "Piranha Millemorsi", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]I Piranha Millemorsi sono pesci d'acqua dolce aggressivi capaci di divorare qualsiasi cosa!\n\n I loro banchi si trovano soprattutto nei grandi laghi e nei sistemi fluviali sparpagliati nelle Isole dei Draghi.\n\n Sono particolarmente attivi nelle regioni delle Pianure di Ohn'ahra e delle Sponde del Risveglio."}
MultiLanguageSpellData['it'][393060] = {name = "Pesce Scorpione Ceruleo", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]Il Pesce Scorpione Ceruleo è dotato di molte scaglie taglienti.\n\n Questi banchi di pesci d'acqua salata si trovano soprattutto nell'oceano e nei bacini d'acqua a esso collegato.\n\n Sono particolarmente attivi alle foci dei fiumi nelle Sponde del Risveglio."}
MultiLanguageSpellData['it'][393061] = {name = "Falena di Mare", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]La Falena di Mare scivola sul fondo dell'oceano e vola verso l'alto se sospetta che ci sia una prelibatezza!\n\n Questi banchi di pesci d'acqua salata si trovano soprattutto nell'oceano e nei bacini d'acqua a esso collegato.\n\n Sono particolarmente attivi nelle aree di Iskaara nella Vastità Azzurra."}
MultiLanguageSpellData['it'][393063] = {name = "Sgombro Panzascaglia", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]Gli Sgombri Panzascaglia sono pesci incredibilmente comuni delle Isole dei Draghi e si possono trovare in qualsiasi specchio d'acqua.\n\n Rilanciare uno Sgombro Panzascaglia in acqua è un esercizio che fanno anche i pescatori più esperti."}
MultiLanguageSpellData['it'][393064] = {name = "Corifena delle Isole", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]La Corifena delle Isole è un pesce elusivo, la cui pinna si dice ricordi le Isole dei Draghi.\n\n Si può trovare in tutti i bacini d'acqua delle isole."}
MultiLanguageSpellData['it'][393065] = {name = "Tesoro Scintillante", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]Dei Tesori Scintillanti possono comparire in qualsiasi specchio d'acqua delle Isole dei Draghi. Tutti i pescatori sperano di poterne trovare uno, perché possono contenere tesori incredibili.\n\nPescare in questi banchi aumenta significativamente la probabilità di trovare tesori rari."}
MultiLanguageSpellData['it'][393066] = {name = "Tonno Pinnabrina", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]I Tonni Pinnabrina sono pesci grandi e grossi che vivono sotto sottili lastre di ghiaccio, e riescono a sopravvivere alle basse temperature grazie a uno spesso strato di grasso.\n\n Si possono trovare banchi di questi pesci soprattutto nelle zone fredde delle Isole dei Draghi.\n\n I Tuskarr di Iskaara sono esperti nella pesca di questi esemplari."}
MultiLanguageSpellData['it'][393067] = {name = "Plesiosauro del Magma", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]I Plesiosauri del Magma sono pesci robusti, con una scorza resistente composta da vari minerali.\n\n Si possono trovare banchi di questi pesci soprattutto nei climi caldi delle Isole dei Draghi.\n\n I Tuskarr di Iskaara sono esperti nella pesca di questi esemplari."}
MultiLanguageSpellData['it'][393068] = {name = "Saltatore Prismatico", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]I Saltatori Prismatici sono pesci curiosi e vivaci, con scaglie che brillano nella luce.\n\n Questi pesci amano salta fuori dall'acqua ed è facile trovarli sulle alture delle Isole dei Draghi.\n\n I Tuskarr di Iskaara sono esperti nella pesca di questi esemplari."}
