MultiLanguageSpellData['it'][393073] = {name = "Potenziamento Equipaggiamento PvP", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Potenzia un pezzo di equipaggiamento dell'Onore o della Conquista della Stagione 1 di Dragonflight al grado successivo.\n\n Un oggetto non può essere potenziato a un grado superiore rispetto a quello permesso dal più alto grado nel PvP classificato raggiunto dal personaggio."}
