MultiLanguageSpellData['it'][394327] = {name = "Veleno Tossico", additional_info = "Portata di 100 m\nIstantaneo\n[q]Impregna le tue armi con un veleno letale che dura 1 ora. Ogni colpo ha una probabilità del 30% di avvelenare il nemico, infliggendo istantaneamente (4.07% of Attack power) danni da natura e riducendone tutte le cure ricevute del 8% per 12 s. Si accumula fino a 3 volte."}
MultiLanguageSpellData['it'][394328] = {name = "Veleno Amplificante", additional_info = "Portata di 100 m\nIstantaneo\n[q]Ricopre le tue armi con un veleno letale che dura 1 ora. Ogni colpo ha una probabilità del 30% di avvelenare il nemico, infliggendo (8.14% of Attack power) danni da natura e di applicare Veleno Amplificante per 12 s. Affondo Venefico può consumare 10 accumuli di Veleno Amplificante per infliggere il 35% di danni aggiuntivi. Massimo 20 accumuli."}
